def watershed_sizes(heights: list[list[int]]) -> list[tuple[int, int, int]]:
    if not heights:
        return []

    rows = len(heights)
    cols = len(heights[0]) if rows else 0

    if cols == 0:
        return []

    def get_flow(r: int, c: int):
        """Return the next cell water flows to, or None if (r,c) is a sink."""
        best_h = None
        best_pos = None
        # Priority order: north, east, south, west
        for nr, nc in ((r - 1, c), (r, c + 1), (r + 1, c), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols:
                h = heights[nr][nc]
                if h < heights[r][c]:
                    if best_h is None or h < best_h:
                        best_h = h
                        best_pos = (nr, nc)
        return best_pos  # None means sink

    # Memoize which sink each cell drains to
    sink_of: dict[tuple[int, int], tuple[int, int]] = {}

    def find_sink(r: int, c: int) -> tuple[int, int]:
        if (r, c) in sink_of:
            return sink_of[(r, c)]

        path = []
        cr, cc = r, c
        while True:
            if (cr, cc) in sink_of:
                sink = sink_of[(cr, cc)]
                break
            nxt = get_flow(cr, cc)
            if nxt is None:
                sink = (cr, cc)
                path.append((cr, cc))
                break
            path.append((cr, cc))
            cr, cc = nxt

        for pr, pc in path:
            sink_of[(pr, pc)] = sink
        return sink

    # Count cells per sink
    counts: dict[tuple[int, int], int] = {}
    for r in range(rows):
        for c in range(cols):
            s = find_sink(r, c)
            counts[s] = counts.get(s, 0) + 1

    result = [(r, c, cnt) for (r, c), cnt in counts.items()]
    result.sort(key=lambda x: (-x[2], x[0], x[1]))
    return result
